function validate([n, present, future, hierarchy, budget]) {
  if (!Number.isInteger(n) || n < 1 || n > 160) return 'n is between 1 and 160.';
  if (present.length !== n || future.length !== n) return 'present and future each need n prices.';
  if ([...present, ...future].some(p => !Number.isInteger(p) || p < 1 || p > 50)) return 'Every price is between 1 and 50.';
  if (!Number.isInteger(budget) || budget < 1 || budget > 160) return 'budget is between 1 and 160.';
  if (hierarchy.length !== n - 1) return 'hierarchy needs exactly n - 1 pairs.';
  const children = Array.from({ length: n + 1 }, () => []);
  const hasBoss = new Array(n + 1).fill(false);
  for (const edge of hierarchy) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each hierarchy entry is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 1 || v < 1 || u > n || v > n || u === v) return 'Each pair holds two different IDs from 1 to n.';
    if (v === 1) return 'Employee 1 has no boss.';
    if (hasBoss[v]) return 'Each employee has at most one direct boss.';
    hasBoss[v] = true;
    children[u].push(v);
  }
  const stack = [1];
  let reached = 0;
  while (stack.length) {
    reached++;
    stack.push(...children[stack.pop()]);
  }
  if (reached !== n) return 'Employee 1 must be above every other employee (no cycles).';
  return null;
}

