function maxProfit(n, present, future, hierarchy, budget) {
  const children = Array.from({ length: n }, () => []);
  for (const [boss, employee] of hierarchy) {
    children[boss - 1].push(employee - 1);
  }
  const merge = (left, right) => {
    const merged = new Array(budget + 1).fill(-Infinity);
    for (let i = 0; i <= budget; i++) {
      if (left[i] === -Infinity) continue;
      for (let j = 0; i + j <= budget; j++) {
        if (right[j] === -Infinity) continue;
        merged[i + j] = Math.max(merged[i + j], left[i] + right[j]);
      }
    }
    return merged;
  };
  const dfs = (employee) => {
    let childrenIfSkip = [0, ...new Array(budget).fill(-Infinity)];
    let childrenIfBuy = [0, ...new Array(budget).fill(-Infinity)];
    for (const child of children[employee]) {
      const [childFull, childHalf] = dfs(child);
      childrenIfSkip = merge(childrenIfSkip, childFull);
      childrenIfBuy = merge(childrenIfBuy, childHalf);
    }
    const options = [];
    for (const price of [present[employee], Math.floor(present[employee] / 2)]) {
      const best = [...childrenIfSkip];
      for (let cost = price; cost <= budget; cost++) {
        best[cost] = Math.max(best[cost], childrenIfBuy[cost - price] + future[employee] - price);
      }
      options.push(best);
    }
    return options;
  };
  return Math.max(...dfs(0)[0]);
}

