function maxProfit(n, present, future, hierarchy, budget) {
  // Try every set of buyers; an employee pays half price when their direct boss is in the set too.
  const bossOf = new Array(n + 1).fill(0);
  for (const [u, v] of hierarchy) bossOf[v] = u;
  let best = 0;
  for (let mask = 0; mask < 2 ** n; mask++) {
    let cost = 0, profit = 0;
    for (let e = 1; e <= n; e++) {
      if (Math.floor(mask / 2 ** (e - 1)) % 2 === 0) continue;
      const boss = bossOf[e];
      const discounted = boss > 0 && Math.floor(mask / 2 ** (boss - 1)) % 2 === 1;
      const paid = discounted ? Math.floor(present[e - 1] / 2) : present[e - 1];
      cost += paid;
      profit += future[e - 1] - paid;
    }
    if (cost <= budget && profit > best) best = profit;
  }
  return best;
}

