function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = int(0, i);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const n = size === 'large' ? (rand() < 0.5 ? 160 : int(100, 160)) : int(1, 10);
  // A narrow price range makes discounts and near-ties matter more often.
  const top = rand() < 0.5 ? 50 : int(2, 12);
  const present = Array.from({ length: n }, () => int(1, top));
  const future = Array.from({ length: n }, () => int(1, top));
  // Employee 1 is the root; the other IDs are shuffled so labels say nothing about depth.
  const ids = [1, ...shuffle(Array.from({ length: n - 1 }, (_, i) => i + 2))];
  const shape = int(0, 3);
  const hierarchy = [];
  for (let i = 1; i < n; i++) {
    const parent = shape === 0 ? i - 1 : shape === 1 ? 0 : shape === 2 ? Math.floor((i - 1) / 2) : int(0, i - 1);
    hierarchy.push([ids[parent], ids[i]]);
  }
  const spend = present.reduce((sum, price) => sum + price, 0);
  const budget = size === 'large' ? (rand() < 0.5 ? 160 : int(60, 160)) : int(1, Math.min(160, spend + 2));
  return [n, present, future, shuffle(hierarchy), budget];
}
